// Simulação de cenários do gerador: monta centenas de repositórios sintéticos (variantes de SQL,
// rotas, menus, edges, workflows, monorepo, Python, arquivos corrompidos, fuzz) e confere:
// não trava, erros_do_gerador vazio, saída determinística e extração esperada.
// Rodar: node scripts/ai-context/cenarios.mjs  [--only <trecho>] [--keep] [--help]
// Sai com 0 se todos passam, 1 se algum falha ou se --only não casa com nenhum cenário, 2 em argumento inválido.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync, spawn, spawnSync } from 'node:child_process';

const GERADOR = path.resolve(path.dirname(new URL(import.meta.url).pathname), 'gerar.mjs');
const USO = `Uso: node scripts/ai-context/cenarios.mjs [--only <trecho>] [--keep] [--help]
  --only <trecho>  roda só os cenários cujo nome contém o trecho (ex.: --only "sql:")
  --keep           não apaga os repositórios temporários (para inspecionar uma falha)
  --help, -h       mostra esta ajuda`;
const uso = (msg) => { console.error(`${msg}\n${USO}`); process.exit(2); };
let ONLY = null, KEEP = false;
for (let i = 2; i < process.argv.length; i++) {
  const a = process.argv[i];
  if (a === '--help' || a === '-h') { console.log(USO); process.exit(0); }
  else if (a === '--keep') KEEP = true;
  else if (a === '--only' || a.startsWith('--only=')) { ONLY = a === '--only' ? process.argv[++i] : a.slice(7); if (!ONLY || (a === '--only' && ONLY.startsWith('--'))) uso('--only exige um trecho do nome do cenário.'); }
  else uso(`argumento desconhecido: ${a}`);
}
const w = (root, rel, text) => { const p = path.join(root, rel); fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, text); };
const PKG = (extra = {}) => JSON.stringify({ name: 'x', version: '0.0.1', scripts: { test: 'vitest' }, dependencies: { react: '18', 'react-router-dom': '6', '@supabase/supabase-js': '2' }, ...extra });
const TSCONFIG = JSON.stringify({ compilerOptions: { strict: true, paths: { '@/*': ['./src/*'] } } });
const scenarios = [];
const sc = (nome, build, check, opts = {}) => scenarios.push({ nome, build, check, ...opts });
const run = (root) => { execFileSync(process.execPath, [GERADOR, '--quiet'], { cwd: root, stdio: ['ignore', 'pipe', 'pipe'] }); const J = (f) => JSON.parse(fs.readFileSync(path.join(root, 'inventario/ia', f), 'utf8')); return J; };
const git = (root) => { try { execFileSync('git', ['init', '-q'], { cwd: root }); execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', 'add', '-A'], { cwd: root }); execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', 'commit', '-q', '-m', 'feat: x'], { cwd: root }); } catch {} };
const base = (root) => { w(root, 'package.json', PKG()); w(root, 'tsconfig.json', TSCONFIG); };
const eq = (a, b, msg) => { if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(`${msg}: esperado ${JSON.stringify(b)} obtido ${JSON.stringify(a)}`); };
const ok = (c, msg) => { if (!c) throw new Error(msg); };

// ---------------- SQL / banco ----------------
const sqlCases = {
  'create simples': ['create table public.t (id uuid primary key, a text not null);', (b) => { eq(Object.keys(b.tabelas.t.colunas), ['a', 'id'], 'colunas'); eq(b.tabelas.t.colunas.a.nn, true, 'nn'); }],
  'sem schema': ['CREATE TABLE t (id int);', (b) => ok(b.tabelas.t, 't')],
  'aspas duplas': ['create table "public"."T" ("Id" int, "createdAt" timestamptz);', (b) => eq(Object.keys(b.tabelas.T.colunas), ['Id', 'createdAt'], 'cols')],
  'if not exists + unlogged': ['create unlogged table if not exists public.t (id int);', (b) => ok(b.tabelas.t, 't')],
  'schema auth': ['create table auth.x (id int);', (b) => ok(b.tabelas['auth.x'] && !b.tabelas.x, 'auth.x')],
  'multilinha e comentarios': ['create table public.t (\n  id uuid primary key, -- chave\n  /* bloco */ nome text default \'a;b\',\n  n numeric(10,2) default 0\n);', (b) => { eq(Object.keys(b.tabelas.t.colunas), ['id', 'n', 'nome'], 'cols'); eq(b.tabelas.t.colunas.n.tipo, 'numeric(10,2)', 'tipo'); }],
  'check e constraint inline': ['create table public.t (id int, s text check (s in (\'a\',\'b\')), constraint pk primary key (id), foreign key (id) references public.u(id));', (b) => { eq(Object.keys(b.tabelas.t.colunas), ['id', 's'], 'cols'); eq(b.tabelas.t.fks, ['id->u'], 'fk'); }],
  'array e tipos compostos': ['create table public.t (tags text[], pos double precision, ts timestamp with time zone, cv character varying(20), bv bit varying);', (b) => { eq(b.tabelas.t.colunas.tags.tipo, 'text[]', 'arr'); eq(b.tabelas.t.colunas.pos.tipo, 'double precision', 'dp'); eq(b.tabelas.t.colunas.ts.tipo, 'timestamp with time zone', 'ts'); eq(b.tabelas.t.colunas.cv.tipo, 'character varying(20)', 'cv'); }],
  'generated column': ['create table public.t (a int, b int generated always as (a*2) stored);', (b) => eq(Object.keys(b.tabelas.t.colunas), ['a', 'b'], 'cols')],
  'alter add varias': ['create table public.t (id int); alter table public.t add column a text, add column b int not null default 1;', (b) => { eq(Object.keys(b.tabelas.t.colunas), ['a', 'b', 'id'], 'cols'); eq(b.tabelas.t.colunas.b.default, '1', 'def'); }],
  'alter drop/rename/type': ['create table public.t (id int, a text, b text); alter table public.t drop column a; alter table public.t rename column b to c; alter table public.t alter column c type varchar(5);', (b) => { eq(Object.keys(b.tabelas.t.colunas), ['c', 'id'], 'cols'); eq(b.tabelas.t.colunas.c.tipo, 'varchar(5)', 'tipo'); }],
  'alter set/drop not null/default': ['create table public.t (a text); alter table public.t alter column a set not null; alter table public.t alter column a set default \'x\'; alter table public.t alter column a drop not null; alter table public.t alter column a drop default;', (b) => { eq(b.tabelas.t.colunas.a.nn, false, 'nn'); eq(b.tabelas.t.colunas.a.default, null, 'def'); }],
  'rename table': ['create table public.a (id int); alter table public.a rename to b;', (b) => ok(!b.tabelas.a && b.tabelas.b, 'rename')],
  'drop table': ['create table public.a (id int); drop table if exists public.a cascade;', (b) => ok(!b.tabelas.a, 'drop')],
  'rls + policies ordem': ['create table public.t (id int); alter table public.t enable row level security; create policy "p" on public.t for select to authenticated using (true); drop policy "p" on public.t; create policy "p" on public.t as restrictive for update to service_role using (true) with check (true);', (b) => { eq(b.tabelas.t.rls, true, 'rls'); eq(b.tabelas.t.policies, [{ nome: 'p', comando: 'update', para: 'service_role', tipo: 'restrictive' }], 'pol'); }],
  'policy sem for/to': ['create table public.t (id int); create policy p on t using (true);', (b) => eq(b.tabelas.t.policies[0], { nome: 'p', comando: 'all', para: 'public', tipo: 'permissive' }, 'pol')],
  'policy em DO block': ['create table public.t (id int); do $$ begin create policy "p" on public.t for select to anon using (true); end $$;', (b) => eq(b.tabelas.t.policies[0].para, 'anon', 'pol DO')],
  'policy em funcao plpgsql': ['create table public.t (id int); create or replace function f() returns void language plpgsql as $f$ begin create policy "p" on public.t for select using (true); end $f$;', (b) => { ok(b.funcoes.includes('f'), 'fn'); eq(b.tabelas.t.policies.length, 1, 'pol fn'); }],
  'ddl dinamico': ['create table public.t (id int); do $$ begin execute format(\'create policy %I on public.t for select using (true)\', \'p\'); end $$;', (b) => eq(b.avisos.length, 1, 'aviso')],
  'index': ['create table public.t (a int, b int); create unique index concurrently if not exists t_ab on public.t using btree (a, b desc); drop index if exists t_ab; create index t_a on t (a);', (b) => eq(b.tabelas.t.indices, [{ nome: 't_a', colunas: 'a', unico: false }], 'idx')],
  'trigger': ['create table public.t (id int); create or replace function public.fn() returns trigger as $$ begin return new; end $$ language plpgsql; create trigger trg before insert or update on public.t for each row execute procedure public.fn(); drop trigger if exists trg on public.t; create trigger trg2 after delete on public.t for each statement execute function fn();', (b) => eq(b.triggers.map((t) => t.nome + ':' + t.evento), ['trg2:delete'], 'trg')],
  'view / mview': ['create table public.t (id int); create or replace view public.v as select * from t; create materialized view public.mv as select 1; drop view v;', (b) => eq(b.views, ['mv'], 'views')],
  'enum + alter type': ['create type public.st as enum (\'a\', \'b\'); alter type public.st add value if not exists \'c\';', (b) => eq(b.enums.st, ['a', 'b', 'c'], 'enum')],
  'extension': ['create extension if not exists "uuid-ossp"; create extension pg_cron;', (b) => eq(b.extensoes, ['pg_cron', 'uuid-ossp'], 'ext')],
  'cron schedule/unschedule': ['select cron.schedule(\'job1\', \'*/5 * * * *\', $$select 1$$); select cron.schedule(\'job2\', \'0 0 * * *\', \'select net.http_post(url:=\'\'https://x.supabase.co/functions/v1/tick\'\')\'); select cron.unschedule(\'job1\');', (b) => eq(b.cron_jobs.map((c) => c.nome + (c.chama_edge ? '>' + c.chama_edge : '')), ['job2>tick'], 'cron')],
  'bucket': ['insert into storage.buckets (id, name, public) values (\'avatars\', \'avatars\', true) on conflict do nothing;', (b) => eq(b.buckets.map((x) => x.nome), ['avatars'], 'bucket')],
  'partition of': ['create table public.p (id int) partition by range (id); create table public.p1 partition of public.p for values from (1) to (10);', (b) => ok(b.tabelas.p && b.tabelas.p1, 'part')],
  'create table as': ['create table public.c as select 1 as x;', (b) => ok(b.tabelas.c, 'ctas')],
  'CRLF': ['create table public.t (\r\n id int,\r\n a text\r\n);\r\n', (b) => eq(Object.keys(b.tabelas.t.colunas), ['a', 'id'], 'crlf')],
  'ponto e virgula em string': ['create table public.t (a text default \'x;y\'); create table public.u (id int);', (b) => ok(b.tabelas.t && b.tabelas.u, 'semi')],
  'maiusculas': ['CREATE TABLE PUBLIC.T (ID INT NOT NULL, A TEXT); ALTER TABLE PUBLIC.T ENABLE ROW LEVEL SECURITY;', (b) => { ok(b.tabelas.T, 'T'); eq(b.tabelas.T.rls, true, 'rls'); }],
  'sql vazio / so comentarios': ['-- nada\n/* nada */', (b) => eq(Object.keys(b.tabelas), [], 'vazio')],
  'sql corrompido': ['create table public.t (id int; alter tabl x; ))))(((( create policy', (b) => ok(true, 'nao travou')],
  'fk via alter': ['create table public.a (id int); create table public.b (a_id int); alter table public.b add constraint b_a foreign key (a_id) references public.a (id) on delete cascade;', (b) => eq(b.tabelas.b.fks, ['a_id->a'], 'fk')],
};
for (const [nome, [sql, chk]] of Object.entries(sqlCases)) sc(`sql: ${nome}`, (r) => { base(r); w(r, 'supabase/migrations/001.sql', sql); }, (J) => chk(J('banco.json')));
sc('sql: schema proprio em funcao/view/enum/trigger/drop index', (r) => { base(r); w(r, 'supabase/migrations/001.sql', "create table app.t (id int); create index t_i on app.t (id); drop index app.t_i; create function app.f() returns trigger language plpgsql as $$ begin return new; end $$; create function \"app\".\"g\"() returns int language sql as $$ select 1 $$; drop function app.g(); create trigger trg before insert on app.t for each row execute function app.f(); create view app.v as select 1; create materialized view app.mv as select 1; drop materialized view app.mv; create type app.st as enum ('a'); alter type app.st add value 'b';"); }, (J) => { const b = J('banco.json'); eq(b.funcoes, ['app.f'], 'fn'); eq(b.views, ['app.v'], 'view'); eq(b.enums, { 'app.st': ['a', 'b'] }, 'enum'); eq(b.triggers[0].funcao, 'app.f', 'trg'); eq(b.tabelas['app.t'].indices, [], 'drop index'); });
sc('sql: sobrecarga de funcao (drop de assinatura antiga nao apaga a nova)', (r) => { base(r); w(r, 'supabase/migrations/001.sql', "create function public.f(a int) returns int language sql as $$ select 1 $$; create function public.f(a int, b text default 'x,y') returns int language sql as $$ select 2 $$; drop function public.f(int); create function public.g() returns int language sql as $$ select 1 $$; drop function if exists public.g; create function h(a int) returns int language sql as $$ select 1 $$; drop function h(int);"); }, (J) => eq(J('banco.json').funcoes, ['f'], 'sobrecarga'));
sc('sql: supabase em subpasta (migrations, config.toml, functions, pgTAP), SQL de docs fora e supabase/.temp na raiz ignorado', (r) => { base(r); w(r, 'db-site/supabase/migrations/1.sql', 'create table public.t (id int);'); w(r, 'db-site/supabase/config.toml', '[functions.hook]\nverify_jwt = false\n'); w(r, 'db-site/supabase/functions/hook/index.ts', 'Deno.serve(() => new Response("ok"));'); w(r, 'db-site/supabase/tests/database/a.test.sql', 'select 1;'); w(r, 'docs/sql/outro-banco.sql', 'create table public.de_outro_banco (id int);'); w(r, 'supabase/.temp/cli-latest', 'v2'); }, (J) => { const b = J('banco.json'); eq(Object.keys(b.tabelas), ['t'], 'so migrations'); eq(b.fonte, ['db-site/supabase/migrations'], 'fonte'); eq(J('edge-functions.json').verify_jwt_false, ['hook'], 'config.toml'); eq(J('edge-functions.json').pasta, 'db-site/supabase/functions', 'edge dir'); eq(J('testes.json').sql, ['db-site/supabase/tests/database/a.test.sql'], 'pgtap'); });
sc('sql: types.ts com varios schemas', (r) => { base(r); w(r, 'supabase/migrations/1.sql', 'create table priv.t (id int, a int); create table public.u (x int);'); w(r, 'src/integrations/supabase/types.ts', 'export type Database = {\n  public: {\n    Tables: {\n      u: {\n        Row: {\n          x: number\n        }\n      }\n    }\n  }\n  priv: {\n    Tables: {\n      t: {\n        Row: {\n          id: number\n          b: number\n        }\n      }\n    }\n  }\n}'); }, (J) => { const b = J('banco.json'); eq(b.tabelas['priv.t'].drift, { so_na_migration: ['a'], so_no_types: ['b'] }, 'drift priv'); eq(b.tabelas.u.drift, { so_na_migration: [], so_no_types: [] }, 'public'); ok(!b.tabelas.t, 'sem tabela fantasma em public'); });
sc('sql: rpc por helper, URL REST e literal de funcao conhecida', (r) => { base(r); w(r, 'supabase/migrations/1.sql', 'create function public.f1() returns int language sql as $$ select 1 $$; create function public.f2() returns int language sql as $$ select 1 $$; create function public.f3() returns int language sql as $$ select 1 $$; create function public.f4() returns int language sql as $$ select 1 $$; create function public.solta() returns int language sql as $$ select 1 $$;'); w(r, 'src/a.ts', "async function rpc<T>(name: string): Promise<T> { return fetch(`/rest/v1/rpc/${name}`); }\nawait rpc<{ a?: number }>('f1');\nawait fetch(`${url}/rest/v1/rpc/f2`);\nconst nome = cond ? 'f3' : 'inexistente';\nawait supabase.rpc('f4');"); w(r, 'src/b.ts', "export const titulo = 'solta';"); }, (J) => eq(J('banco.json').rpcs_usadas_no_codigo.map((x) => x.nome + ':' + x.definida), ['f1:true', 'f2:true', 'f3:true', 'f4:true'], 'rpcs'));
sc('sql: muitas migrations em ordem (200)', (r) => { base(r); for (let i = 0; i < 200; i++) w(r, `supabase/migrations/${String(i).padStart(3, '0')}.sql`, i === 0 ? 'create table public.t (id int);' : `alter table public.t add column c${i} int;`); }, (J) => eq(Object.keys(J('banco.json').tabelas.t.colunas).length, 200, 'cols'));
sc('sql: migrations em pasta alternativa', (r) => { base(r); w(r, 'db/migrations/1.sql', 'create table t (id int);'); }, (J) => ok(J('banco.json').tabelas.t, 't'));
sc('sql: prisma', (r) => { base(r); w(r, 'prisma/schema.prisma', 'model User {\n  id Int @id @default(autoincrement())\n  email String @unique\n  posts Post[]\n}\nmodel Post {\n  id Int @id\n  author User @relation(fields: [authorId], references: [id])\n  authorId Int\n}\nenum Role { ADMIN USER }'); }, (J) => { const b = J('banco.json'); eq(Object.keys(b.tabelas.User.colunas), ['email', 'id', 'posts'], 'prisma'); eq(b.tabelas.Post.fks, ['author->User'], 'fk'); eq(b.enums.Role, ['ADMIN', 'USER'], 'enum'); });
sc('sql: drizzle', (r) => { base(r); w(r, 'src/db/schema.ts', "import { pgTable, text, uuid } from 'drizzle-orm/pg-core';\nexport const users = pgTable('users', { id: uuid('id').primaryKey(), name: text('name').notNull() });"); }, (J) => eq(Object.keys(J('banco.json').tabelas.users.colunas), ['id', 'name'], 'drizzle'));
sc('sql: typeorm', (r) => { base(r); w(r, 'src/entities/User.ts', "@Entity('users')\nexport class User {\n  @PrimaryGeneratedColumn()\n  id: number;\n  @Column()\n  name: string;\n}"); }, (J) => eq(Object.keys(J('banco.json').tabelas.users.colunas), ['id', 'name'], 'typeorm'));
sc('sql: types.ts balanceado', (r) => { base(r); w(r, 'src/integrations/supabase/types.ts', 'export type Database = { public: { Tables: { t: { Row: { id: string; nested: { a: string } | null; }; Insert: {} }; u: { Row: { x: number } } }; Views: { v: { Row: { q: number } } } } }'); }, (J) => { const b = J('banco.json'); eq(Object.keys(b.tabelas.t.colunas_types), ['id', 'nested'], 't'); ok(b.tabelas.u, 'u'); ok(!b.tabelas.v, 'view nao vira tabela'); });
sc('sql: drift', (r) => { base(r); w(r, 'supabase/migrations/1.sql', 'create table public.t (id int, a int);'); w(r, 'src/integrations/supabase/types.ts', 'export type Database = { public: { Tables: { t: { Row: { id: number; b: number } } } } }'); }, (J) => eq(J('banco.json').tabelas.t.drift, { so_na_migration: ['a'], so_no_types: ['b'] }, 'drift'));
sc('sql: uso no front/edges/testes', (r) => { base(r); w(r, 'supabase/migrations/1.sql', 'create table public.t (id int);'); w(r, 'src/a.ts', "supabase.from('t'); supabase.from('fantasma'); supabase.rpc('r1');"); w(r, 'src/a.test.ts', "supabase.from('so_teste');"); w(r, 'supabase/functions/f/index.ts', "supabase.from('t');"); }, (J) => { const b = J('banco.json'); eq(b.tabelas.t.usada_no_front, 1, 'front'); eq(b.tabelas.t.usada_em_edges, ['f'], 'edges'); eq(b.tabelas_usadas_no_codigo_sem_definicao, ['fantasma'], 'sem def'); eq(b.rpcs_usadas_no_codigo, [{ nome: 'r1', definida: false, usada_em: 1 }], 'rpc'); });

// ---------------- rotas ----------------
const route = (jsx, imports = '') => `import { Routes, Route } from 'react-router-dom';\n${imports}\nexport const App = () => (<Routes>${jsx}</Routes>);`;
const comp = (r, name, dir = 'src/pages') => w(r, `${dir}/${name}.tsx`, `export const ${name} = () => <div/>;`);
sc('rotas: element simples', (r) => { base(r); comp(r, 'A'); w(r, 'src/App.tsx', route('<Route path="/a" element={<A />} />', "import { A } from '@/pages/A';")); }, (J) => eq(J('rotas.json').urls[0].arquivo, 'src/pages/A.tsx', 'a'));
sc('rotas: aspas simples e multilinha', (r) => { base(r); comp(r, 'A'); w(r, 'src/App.tsx', route("<Route\n  path='/a'\n  element={\n    <A />\n  }\n/>", "import { A } from '@/pages/A';")); }, (J) => eq(J('rotas.json').urls[0].arquivo, 'src/pages/A.tsx', 'a'));
sc('rotas: aninhadas 3 niveis + index + relativa + absoluta', (r) => { base(r); comp(r, 'L'); comp(r, 'A'); comp(r, 'B'); comp(r, 'C'); w(r, 'src/App.tsx', route('<Route path="/x" element={<L/>}><Route index element={<A/>}/><Route path="y" element={<B/>}><Route path="/abs" element={<C/>}/></Route></Route>', "import { L } from '@/pages/L'; import { A } from '@/pages/A'; import { B } from '@/pages/B'; import { C } from '@/pages/C';")); }, (J) => { const u = J('rotas.json').urls; eq(u.map((x) => x.caminho + ':' + (x.arquivo || '').split('/').pop()), ['/abs:C.tsx', '/x:L.tsx', '/x:A.tsx', '/x/y:B.tsx'], 'nest'); });
sc('rotas: wrapper protegido + componente interno + herança', (r) => { base(r); comp(r, 'A'); comp(r, 'B'); w(r, 'src/components/auth/Protected.tsx', 'export const Protected = ({children}) => children;'); w(r, 'src/App.tsx', route('<Route path="/a" element={<Protected><A/></Protected>}><Route path="b" element={<B/>}/></Route>', "import { A } from '@/pages/A'; import { B } from '@/pages/B'; import { Protected } from '@/components/auth/Protected';")); }, (J) => { const u = Object.fromEntries(J('rotas.json').urls.map((x) => [x.caminho, x])); eq(u['/a'].arquivo, 'src/pages/A.tsx', 'a'); eq(u['/a'].protegida, true, 'prot'); eq(u['/a/b'].protegida, true, 'heranca'); eq(u['/a'].wrappers, ['Protected'], 'wrap'); });
sc('rotas: Component prop (LazyPage)', (r) => { base(r); comp(r, 'A'); w(r, 'src/App.tsx', route('<Route path="/a" element={<LazyPage Component={A} />} />', "import { A } from '@/pages/A'; import { LazyPage } from '@/components/LazyPage';")); w(r, 'src/components/LazyPage.tsx', 'export const LazyPage = ({Component}) => <Component/>;'); }, (J) => eq(J('rotas.json').urls[0].arquivo, 'src/pages/A.tsx', 'a'));
