  w(r, 'graphify-out/graph.json', JSON.stringify({ nodes: [{ id: 'a', label: 'a', source_file: 'src/a.ts', community: 1 }], links: [{ source: 'a', target: 'a', relation: 'calls' }] })); again();
  ok(idx().includes('commit do grafo não informado'), 'sem commit'); ok(!idx().includes('DESATUALIZADO'), 'nao afirma desatualizado');
  w(r, 'graphify-out/project-meta.json', JSON.stringify({ commit: head })); again();
  eq([J('grafo-graphify.json').grafo_atual, J('grafo-graphify.json').commit_do_grafo], [true, head], 'atual'); ok(idx().includes('`pnpm run graph:query -- "<pergunta>"`'), 'consulta do repo');
