// fuzz: 120 repos aleatórios misturando trechos reais — só precisa não travar e sair sem erros de seção
const SNIPPETS = ["create table public.{t} (id uuid primary key, {c} text);", "alter table public.{t} add column {c} int;", "create policy \"{t}_p\" on public.{t} for select using (true);", "drop table if exists public.{t};", "do $$ begin alter table public.{t} enable row level security; end $$;", "select cron.schedule('{t}', '* * * * *', 'select 1');", "create index {t}_i on public.{t} ({c});", "create or replace function public.{t}_fn() returns void as $$ begin end $$ language plpgsql;", "<<broken sql ;;; (((", "create type {t}_e as enum ('a');"];
const JS = ["export const {C} = () => <div>{C}</div>;", "import { use{C} } from '@/hooks/use{C}';\nexport function {C}Page() { use{C}(); return <{C}/>; }", "export const use{C} = () => supabase.from('{t}').select('*');", "<Route path=\"/{t}\" element={<{C}Page/>} />", "export const items = [{ label: '{C}', path: '/{t}' }];", "supabase.functions.invoke('{t}-fn');", "const x = {{ unbalanced", "export default function {C}() { return null }", "export * from './{C}';", "app.get('/{t}', h);"];
for (let i = 0; i < 120; i++) {
  sc(`fuzz #${i}`, (r) => {
    base(r); let seed = 1000 + i; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647; const pick = (a) => a[Math.floor(rnd() * a.length)];
    const nSql = Math.floor(rnd() * 8), nJs = Math.floor(rnd() * 12);
    for (let k = 0; k < nSql; k++) { const t = 't' + Math.floor(rnd() * 5), c = 'c' + Math.floor(rnd() * 5); w(r, `supabase/migrations/${k}.sql`, pick(SNIPPETS).replace(/\{t\}/g, t).replace(/\{c\}/g, c)); }
    for (let k = 0; k < nJs; k++) { const C = 'C' + Math.floor(rnd() * 6), t = 't' + Math.floor(rnd() * 5); const dir = pick(['src/pages', 'src/components/x', 'src/hooks', 'src/lib', 'src/components/layout/nav']); w(r, `${dir}/${pick(['', 'use'])}${C}${pick(['', 'Page', 'Nav'])}.${pick(['tsx', 'ts'])}`, pick(JS).replace(/\{C\}/g, C).replace(/\{t\}/g, t) + (rnd() > 0.5 ? '\n' + pick(JS).replace(/\{C\}/g, C).replace(/\{t\}/g, t) : '')); }
    if (rnd() > 0.5) w(r, 'src/App.tsx', route(Array.from({ length: Math.floor(rnd() * 5) }, () => pick(JS)[3] ? `<Route path="/${pick(['a', 'b', 'c'])}" element={<${pick(['C0', 'C1', 'C2'])}Page/>}/>` : '').join('')));
    if (rnd() > 0.7) w(r, 'supabase/functions/t1-fn/index.ts', "Deno.serve(() => { Deno.env.get('X'); supabase.from('t1'); });");
  }, (J) => eq(J('manifest.json').erros, [], 'fuzz sem erros'));
}

// ---------------- runner ----------------
const toRun = scenarios.filter((s) => !ONLY || s.nome.includes(ONLY));
if (!toRun.length) { console.error(`nenhum cenário contém "${ONLY}" no nome (${scenarios.length} cenários existem; veja os nomes no arquivo).`); process.exit(1); }
let pass = 0; const fails = [];
const t0 = Date.now();
for (const s of toRun) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'ctx-sc-'));
  try {
    s.build(root);
    if (!(s.nogit)) git(root);
    const J = run(root);
    s.check(J, root);
    pass++;
  } catch (e) { fails.push({ nome: s.nome, erro: String(e.stderr || e.message || e).split('\n').slice(0, 4).join(' | ') }); }
  if (!KEEP) fs.rmSync(root, { recursive: true, force: true });
}
console.log(`cenários: ${toRun.length} · pass: ${pass} · fail: ${fails.length} · ${((Date.now() - t0) / 1000).toFixed(1)}s`);
for (const f of fails) console.log(`FAIL ${f.nome}\n   ${f.erro}`);
process.exitCode = fails.length ? 1 : 0;
